                "urduAns": "\u062c\u0628 \u0628\u0627\u0631\u0634 \u0631\u06a9 \u06af\u0626\u06cc \u0627\u0648\u0631 \u06c1\u0631 \u0637\u0631\u0641 \u0633\u0648\u0631\u062c \u0686\u0645\u06a9 \u0631\u06c1\u0627 \u062a\u06be\u0627\u060c \u062a\u0648 \u0645\u06cc\u06ba \u0628\u0627\u06c1\u0631 \u06a9\u06be\u06cc\u0644\u0646\u06d2 \u0646\u06a9\u0644\u0627 \u0627\u0648\u0631 \u0645\u062c\u06be\u06d2 \u0631\u0627\u0633\u062a\u06d2 \u0645\u06cc\u06ba \u0627\u06cc\u06a9 \u0686\u06be\u0648\u0679\u0627 \u06a9\u06cc\u0691\u0627 \u0645\u0644\u0627\u06d4 \u0648\u06c1 \u06a9\u06cc\u0691\u0627 \u0627\u062a\u0646\u06cc \u062a\u06cc\u0632\u06cc \u0633\u06d2 \u062f\u0648\u0691 \u0631\u06c1\u0627 \u062a\u06be\u0627 \u062c\u062a\u0646\u0627 \u0648\u06c1 \u062f\u0648\u0691 \u0633\u06a9\u062a\u0627 \u062a\u06be\u0627\u060c \u06cc\u06c1\u0627\u06ba \u062a\u06a9 \u06a9\u06c1 \u0648\u06c1 \u062f\u06be\u0648\u067e \u0645\u06cc\u06ba \u0633\u0627\u0646\u0633 \u0644\u06cc\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0631\u06a9\u0627\u06d4 \u067e\u06be\u0631 \u0627\u0633 \u0646\u06d2 \u0627\u06cc\u06a9 \u0646\u063a\u0645\u06c1 \u06af\u0646\u06af\u0646\u0627\u06cc\u0627 \u0627\u0648\u0631 \u0627\u067e\u0646\u06d2 \u067e\u0631\u0648\u06ba \u06a9\u0648 \u06c1\u0644\u0627\u06cc\u0627\u060c \u0627\u0648\u0631 \u0627\u0633 \u0637\u0631\u062d \u0627\u0633 \u0646\u06d2 \u062f\u06a9\u06be\u0627\u06cc\u0627 \u06a9\u06c1 \u0648\u06c1 \u06a9\u06cc\u0691\u0627 \u0628\u0646 \u06a9\u0631 \u06a9\u062a\u0646\u0627 \u062e\u0648\u0634 \u06c1\u06d2!",
                "pashto": "\u062f \u062f\u0631\u0633 \u0645\u0647\u0645 \u0627\u062e\u0644\u0627\u0642\u064a \u0627\u0648 \u069a\u0648\u0648\u0646\u06cc\u0632 \u067c\u06a9\u064a \u067e\u0647 \u062e\u067e\u0644\u0648 \u067c\u06a9\u0648 \u06a9\u06d0 \u0628\u06cc\u0627\u0646 \u06a9\u0693\u0626.",
