        "pashto": "\u062f \u062e\u0627\u0644\u064a \u067e\u0647 \u0633\u0647\u0627\u0631 \u0639\u0644\u064a \u0627\u0648 \u062f \u0647\u063a\u0647 \u0646\u06cc\u06a9\u0647 \u067e\u0647 \u0628\u0627\u063a \u06a9\u06d0 \u0648\u0646\u06d0 \u06a9\u06d0\u0646\u0648\u0644\u06d0. \u0646\u06cc\u06a9\u0647 \u0648\u0631\u062a\u0647 \u0648\u0648\u06cc\u0644 \u0686\u06d0 \u0648\u0646\u06d0 \u0632\u0645\u0648\u0646\u0696 \u063a\u0648\u0631\u0647 \u0645\u0644\u06ab\u0631\u064a \u062f\u064a\u060c \u0647\u063a\u0648\u06cc \u0633\u06cc\u0648\u0631\u06cc\u060c \u067e\u0627\u06a9\u0647 \u0647\u0648\u0627 \u0627\u0648 \u0645\u06d0\u0648\u06d0 \u0631\u0627\u06a9\u0648\u064a \u0627\u0648 \u0645\u0631\u063a\u0627\u0646 \u067e\u0647 \u06a9\u06d0 \u0681\u0627\u0644\u06d0 \u062c\u0648\u0693\u0648\u064a. \u0639\u0644\u064a \u062f \u0622\u0645\u0648\u0646\u0648 \u06cc\u0648 \u0646\u06cc\u0627\u0644\u06ab\u06cc \u06a9\u06d0\u0646\u0627\u0648\u0647 \u0627\u0648 \u0627\u0648\u0628\u0647 \u06cc\u06d0 \u0648\u0631\u06a9\u0693\u06d0."
