        "pashto": "\u06cc\u0648\u0647 \u062a\u0696\u06d0 \u0645\u06cc\u0696\u06cc \u067e\u0647 \u0633\u06cc\u0646\u062f \u06a9\u06d0 \u0689\u0648\u0628\u06d0\u062f\u0644\u0647. \u06cc\u0648\u06d0 \u06a9\u0648\u062a\u0631\u06d0 \u062f \u0648\u0646\u06d0 \u067e\u0627\u06bc\u0647 \u067e\u0647 \u0627\u0648\u0628\u0648 \u06a9\u06d0 \u0648\u0627\u0686\u0648\u0644\u0647 \u0627\u0648 \u0645\u06cc\u0696\u06cc \u0648\u0698\u063a\u0648\u0631\u0644 \u0634\u0648\u0647. \u0648\u0631\u0648\u0633\u062a\u0647 \u06cc\u0648 \u069a\u06a9\u0627\u0631\u064a \u063a\u0648\u069a\u062a\u0644 \u06a9\u0648\u062a\u0631\u0647 \u0648\u0648\u0644\u064a\u060c \u062e\u0648 \u0645\u06cc\u0696\u06cc \u062f \u069a\u06a9\u0627\u0631\u064a \u067e\u069a\u0647 \u0648\u0686\u06cc\u0686\u0644\u0647. \u06a9\u0648\u062a\u0631\u0647 \u0648\u0627\u0644\u0648\u062a\u0644\u0647 \u0627\u0648 \u062e\u0648\u0646\u062f\u064a \u0634\u0648\u0647. \u067e\u0627\u06cc\u0644\u0647: \u062f \u0646\u06d0\u06a9\u06cd \u0628\u062f\u0644\u0647 \u0646\u06d0\u06a9\u064a \u062f\u0647."
