                "urduAns": "\u0646\u0628\u06cc \u06a9\u0631\u06cc\u0645 \ufdfa \u0646\u06d2 \u0641\u0631\u0645\u0627\u06cc\u0627 \u06a9\u06c1 \u062c\u0646\u062a \u0645\u0627\u0624\u06ba \u06a9\u06d2 \u0642\u062f\u0645\u0648\u06ba \u062a\u0644\u06d2 \u06c1\u06d2\u06d4",
                "pashto": "\u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 (\u0635) \u062f \u0645\u06cc\u0646\u062f\u0648 \u067e\u0647 \u0627\u0693\u0647 \u0685\u0647 \u0641\u0631\u0645\u0627\u06cc\u0644\u064a \u062f\u064a\u061f",
