                "urduAns": "\u0648\u0627\u0644\u062f \u0631\u0648\u0632\u06cc \u06a9\u0645\u0627\u0646\u06d2 \u06a9\u06d2 \u0644\u06cc\u06d2 \u0645\u062d\u0646\u062a \u06a9\u0631\u062a\u06d2 \u06c1\u06cc\u06ba \u0627\u0648\u0631 \u062a\u0639\u0644\u06cc\u0645 \u0648 \u062e\u0648\u0631\u0627\u06a9 \u0641\u0631\u0627\u06c1\u0645 \u06a9\u0631\u062a\u06d2 \u06c1\u06cc\u06ba\u06d4",
                "pashto": "\u067e\u0644\u0627\u0631 \u0685\u0646\u06ab\u0647 \u062f \u06a9\u0648\u0631\u0646\u06cd \u067e\u0627\u0644\u0646\u0647 \u06a9\u0648\u064a\u061f",
