                "urdu": "\u06c1\u0645\u06cc\u06ba \u0648\u0627\u0644\u062f\u06cc\u0646 \u06a9\u06d2 \u0644\u06cc\u06d2 \u06a9\u06cc\u0627 \u062f\u0639\u0627 \u0645\u0627\u0646\u06af\u0646\u06cc \u0686\u0627\u06c1\u06cc\u06d2\u061f",
                "urduAns": "\u0631\u0628 \u0627\u0631\u062d\u0645\u0647\u0645\u0627 \u0643\u0645\u0627 \u0631\u0628\u064a\u0627\u0646\u064a \u0635\u063a\u064a\u0631\u0627\u064b (\u0627\u06d2 \u0645\u06cc\u0631\u06d2 \u0631\u0628 \u0627\u0646 \u062f\u0648\u0646\u0648\u06ba \u067e\u0631 \u0631\u062d\u0645 \u0641\u0631\u0645\u0627 \u062c\u06cc\u0633\u0627 \u0627\u0646\u06c1\u0648\u06ba \u0646\u06d2 \u0645\u062c\u06be\u06d2 \u0628\u0686\u067e\u0646 \u0645\u06cc\u06ba \u067e\u0627\u0644\u0627)\u06d4",
                "pashto": "\u062f \u0645\u0648\u0631 \u0627\u0648 \u067e\u0644\u0627\u0631 \u0644\u067e\u0627\u0631\u0647 \u06a9\u0648\u0645\u0647 \u062f\u0639\u0627 \u0628\u0627\u06cc\u062f \u0648\u06a9\u0693\u0648\u061f",
                "pashtoAns": "\u0627\u06cc \u0632\u0645\u0627 \u0631\u0628\u0647! \u067e\u0647 \u0647\u063a\u0648\u06cc \u062f\u0648\u0627\u0693\u0648 \u0631\u062d\u0645 \u0648\u06a9\u0693\u0647 \u0644\u06a9\u0647 \u0685\u0646\u06ab\u0647 \u0686\u06d0 \u0647\u063a\u0648\u06cc \u0632\u0647 \u067e\u0647 \u0645\u0627\u0634\u0648\u0645\u062a\u0648\u0628 \u06a9\u06d0 \u0648\u0631\u0648\u0632\u0644\u0645."
